function sidebar(){let q=$('search').value.toLowerCase();$('chapterList').innerHTML=chapters.filter(c=>(c.title.en+' '+c.title.hi).toLowerCase().includes(q)).map(c=>{let score=state.scores[chapterKey(c)]||0,hasScore=Object.hasOwn(state.scores,chapterKey(c)),full=state.complete[chapterKey(c)],percent=full?1:score/10;return `<button data-chapter="${c.id}" class="${chapter?.id===c.id?'active':''}" ${chapter?.id===c.id?'aria-current="page"':''}><span>${String(c.id).padStart(2,'0')}</span><span class="heading"><span class="en">${esc(c.title.en)}</span><span class="hi">${esc(c.title.hi)}</span>${hasScore?`<small>${t('Best','श्रेष्ठ')}: ${score}/10</small>`:''}</span><svg class="progressRing" viewBox="0 0 28 28" role="img" aria-label="${full?'Complete | पूर्ण':`Quiz ${score}/10`}"><circle cx="14" cy="14" r="10" fill="none" stroke="var(--line)" stroke-width="3"/><circle cx="14" cy="14" r="10" fill="none" stroke="${full?'#b17c1d':'var(--accent)'}" stroke-width="3" stroke-dasharray="${percent*62.83} 62.83" transform="rotate(-90 14 14)"/></svg></button>`}).join('');for(let b of $('chapterList').querySelectorAll('button'))b.onclick=()=>selectChapter(+b.dataset.chapter);let n=chapters.filter(c=>state.complete[chapterKey(c)]).length;$('progress').max=Math.max(1,chapters.length);$('progress').value=n;$('progressText').textContent=`${n} / ${chapters.length} ${t('chapters complete','अध्याय पूर्ण')}`}
const tabs=[['visual','Visual Lab','दृश्य प्रयोगशाला'],['notes','Detailed Notes','विस्तृत नोट्स'],['examples','Solved Examples','हल किए उदाहरण'],['practice','Practice & Test','अभ्यास व परीक्षा'],['revision','Revision Map','पुनरावृत्ति मानचित्र']];function renderTabs(){let ids=tabs.map(x=>x[0]);$('tabs').innerHTML=tabs.map(([id,en,hi])=>`<button id="tab-${id}" role="tab" aria-controls="${id}" aria-selected="${id===active}" tabindex="${id===active?0:-1}">${label(en,hi)}</button>`).join('');for(let[id]of tabs){let b=$('tab-'+id);$(id).hidden=id!==active;$(id).setAttribute('aria-labelledby',b.id);b.onclick=()=>switchTab(id);b.onkeydown=e=>{let i=ids.indexOf(id),next;if(e.key==='ArrowRight')next=ids[(i+1)%ids.length];if(e.key==='ArrowLeft')next=ids[(i+ids.length-1)%ids.length];if(e.key==='Home')next=ids[0];if(e.key==='End')next=ids.at(-1);if(next){e.preventDefault();switchTab(next);$('tab-'+next).focus()}}}}
